script:
(function () {
  'use strict';
  // RMD = prior December 31 balance / Uniform Lifetime Table distribution period for the age reached
  // by the end of the distribution year. Projection: next balance = balance x (1 + return) - RMD.
  // Checked in Node: $300,000 at 73 / 26.5 = $11,320.75; $100,000 at 75 / 24.6 = $4,065.04;
  // start ages 72 (born 1950), 73 (1951 and 1959), 75 (1960); table values checked against
  // IRS Pub. 590-B Appendix B Table III.
  // ---- IRS RMD rules (tax year 2026) ---------------------------------------------
  // Uniform Lifetime Table: IRS Publication 590-B, Appendix B, Table III, in effect for
  // distribution years 2022 and later (Treas. Reg. 1.401(a)(9)-9). Key = age at year-end.
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // RMD starting age (SECURE Act 2019, SECURE 2.0 Act 2022): born 1950 or earlier: 72
  // (70 1/2 if born before July 1, 1949); born 1951-1959: 73; born 1960 or later: 75.
  // --------------------------------------------------------------------------------

  function startAge(birthYear) {
    if (birthYear <= 1950) return 72;
    if (birthYear <= 1959) return 73;
    return 75;
  }
  function divisor(age) {
    if (age >= 120) return UNIFORM_TABLE[120];
    return UNIFORM_TABLE[age] || null;
  }
  // Projects RMDs from the first year one is due (or the chosen year if later) for `count`
  // years. Balance is the prior Dec 31 value; each year it earns `rate` on the full balance
  // and the RMD is taken out by year-end: next = balance x (1 + rate) - rmd.
  function projectRmd(birthYear, rmdYear, balance, rate, count) {
    var first = birthYear + startAge(birthYear);
    var year = Math.max(rmdYear, first);
    var b = balance * Math.pow(1 + rate, year - rmdYear);
    var rows = [];
    for (var i = 0; i < count && b > 0.005; i++, year++) {
      var age = year - birthYear, d = divisor(age);
      if (!d) break;
      var rmd = Math.min(b, b / d);
      rows.push({ year: year, age: age, start: b, divisor: d, rmd: rmd });
      b = Math.max(0, b * (1 + rate) - rmd);
    }
    return { first: first, rows: rows };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var birthYear = Math.round(num('rmBirth')), rmdYear = Math.round(num('rmYear')), balance = num('rmBalance'),
        rate = num('rmRate');
    var error = document.getElementById('rmError');
    var bad = [birthYear, rmdYear, balance, rate].some(isNaN) || birthYear < 1900 || birthYear > 2010 ||
              rmdYear < 2022 || rmdYear > 2100 || rmdYear - birthYear > 120 || balance < 0 || rate < -50 || rate > 30;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a birth year from 1900 to 2010, a distribution year from 2022 to 2100 (age 120 or under), ' +
                          'a non-negative balance and a return from -50% to 30%.';
      return;
    }
    var age = rmdYear - birthYear, sa = startAge(birthYear);
    var p = projectRmd(birthYear, rmdYear, balance, rate / 100, 30);
    set('rmAge', String(age));
    // Born before July 1, 1949: RMDs began at 70 1/2 (all such owners started before 2022).
    set('rmStart', birthYear <= 1948 ? '70\u00bd' : birthYear === 1949 ? '70\u00bd or 72' : sa + ' (' + p.first + ')');
    if (age < sa) {
      set('rmAmountLabel', 'RMD for ' + rmdYear);
      set('rmAmount', money.format(0));
      set('rmDivisor', 'None');
      set('rmNote', 'No RMD is due for ' + rmdYear + '. Your first RMD is for ' + p.first + ', the year you turn ' + sa +
          ', and can be delayed until April 1, ' + (p.first + 1) + '.' +
          (p.rows.length ? ' At the assumed return, it would be about ' + money.format(p.rows[0].rmd) + '.' : ''));
    } else {
      var d = divisor(age), rmd = Math.min(balance, balance / d);
      set('rmAmountLabel', 'RMD for ' + rmdYear);
      set('rmAmount', money.format(rmd));
      set('rmDivisor', d.toFixed(1));
      set('rmNote', age === sa
        ? 'This is your first RMD year. You can take it by December 31, ' + rmdYear + ' or delay it until April 1, ' +
          (rmdYear + 1) + ' (then two RMDs fall in ' + (rmdYear + 1) + '). That is ' + (rmd / balance * 100).toFixed(2) + '% of the balance.'
        : 'Take it by December 31, ' + rmdYear + '. That is ' + (balance > 0 ? (rmd / balance * 100).toFixed(2) : '0.00') + '% of the balance.');
    }
    var body = document.getElementById('rmSchedule');
    body.textContent = '';
    p.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, row.age, money.format(row.start), row.divisor.toFixed(1), money.format(row.rmd)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
